import time

class OrderProcessingError(Exception):
    pass

class PaymentFailedError(OrderProcessingError):
    def __init__(self, reason):
        self.reason = reason
        super().__init__(f'Payment failed: {reason}')

class InventoryUnavailableError(OrderProcessingError):
    def __init__(self, item):
        self.item = item
        super().__init__(f'Inventory unavailable: {item}')

class ShippingAddressError(OrderProcessingError):
    def __init__(self, code):
        self.code = code
        super().__init__(f'Shipping address error: {code}')

class MaxRetriesExceededError(OrderProcessingError):
    def __init__(self, attempts, last_error):
        self.attempts = attempts
        self.last_error = last_error
        super().__init__(f'Max retries ({attempts}) exceeded. Last error: {last_error}')

def process_order(payment_ok, stock_ok, address_ok, max_retries=3, retry_delay=0.1):
    last_error = None
    for attempt in range(1, max_retries + 1):
        try:
            if not payment_ok:
                raise PaymentFailedError('Card declined')
            if not stock_ok:
                raise InventoryUnavailableError('Widget-X')
            if not address_ok:
                raise ShippingAddressError('ZIP-404')
            return 'Order shipped'
        except OrderProcessingError as e:
            last_error = e
            if attempt < max_retries:
                time.sleep(retry_delay)
    raise MaxRetriesExceededError(max_retries, str(last_error))
